
import mlflow
import retail_agent

# ==========================================
# 1. Configure MLflow
# ==========================================

mlflow.set_tracking_uri("sqlite:///mlflow.db")

mlflow.set_experiment("RetailSphere_Agent_Evaluation")


# ==========================================
# 2. Define evaluation questions
# ==========================================

test_cases = [
    {
        "question": "What is the total revenue generated by the business?",
        "expected_tool": "get_total_revenue"
    },
    {
        "question": "Show me the top 3 products by revenue.",
        "expected_tool": "get_top_products"
    },
    {
        "question": "Which Indian state generated the highest revenue?",
        "expected_tool": "get_state_revenue"
    },
    {
        "question": "Show me monthly revenue.",
        "expected_tool": "get_monthly_revenue"
    },
    {
        "question": "What percentage of revenue came from the top 3 products?",
        "expected_tool": "get_top_products_revenue_contribution"
    }
]


# ==========================================
# 3. Run MLflow evaluation
# ==========================================

with mlflow.start_run(run_name="RetailSphere_Tool_Selection"):

    total_tests = len(test_cases)
    passed_tests = 0

    for index, test in enumerate(test_cases, start=1):

        question = test["question"]
        expected_tool = test["expected_tool"]

        print(f"\nTest {index}: {question}")

        answer = retail_agent.run_agent(question)

        actual_tools = retail_agent.last_tool_calls

        passed = expected_tool in actual_tools

        if passed:
            passed_tests += 1

        # Record each test in MLflow
        mlflow.log_metric(
            f"test_{index}_passed",
            int(passed)
        )

        mlflow.log_param(
            f"test_{index}_expected_tool",
            expected_tool
        )

        mlflow.log_param(
            f"test_{index}_actual_tools",
            str(actual_tools)
        )

        print("Expected:", expected_tool)
        print("Actual:", actual_tools)
        print("Result:", "PASS" if passed else "FAIL")

    # ======================================
    # 4. Calculate evaluation metrics
    # ======================================

    accuracy = passed_tests / total_tests

    mlflow.log_metric("total_tests", total_tests)
    mlflow.log_metric("passed_tests", passed_tests)
    mlflow.log_metric("failed_tests", total_tests - passed_tests)
    mlflow.log_metric("tool_selection_accuracy", accuracy)

    print("\n========== MLflow Evaluation ==========")
    print(f"Passed: {passed_tests}/{total_tests}")
    print(f"Tool selection accuracy: {accuracy * 100:.2f}%")
    print("MLflow experiment recorded successfully.")
